// Package library holds the read and write queries for the book catalogue.
//
// Queries are written by hand rather than generated by an ORM. That is the
// point: calibre-web's slowness comes from an ORM turning a list view into a
// join fan-out plus N+1 lookups, and the fix is queries that read one
// denormalised table with a keyset cursor. Hand-written SQL keeps that visible.
package library

import (
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/Karlmit/Klaras-Library/internal/store"
)

// Store runs catalogue queries.
type Store struct {
	pool *pgxpool.Pool
}

// New builds a Store.
func New(pool *pgxpool.Pool) *Store { return &Store{pool: pool} }

// Pool exposes the underlying pool for packages that need their own queries.
func (s *Store) Pool() *pgxpool.Pool { return s.pool }

// searchConfig and sortCollation mirror the schema; see internal/store/lang.go
// for why they are constants rather than literals.
const (
	searchConfig  = store.SearchConfig
	sortCollation = store.SortCollation
)
